-- Run once against an existing v1.1 database after taking a verified backup.
ALTER TABLE users ADD contact VARCHAR(30) NOT NULL DEFAULT '' AFTER name;
ALTER TABLE business_profile ADD email VARCHAR(190) NOT NULL DEFAULT '' AFTER gstin, ADD account_holder VARCHAR(160) NOT NULL DEFAULT '' AFTER state, ADD account_name VARCHAR(160) NOT NULL DEFAULT '' AFTER bank_name, ADD declaration TEXT AFTER branch, ADD financial_year VARCHAR(7) NOT NULL DEFAULT '' AFTER declaration, ADD signature VARCHAR(80) NOT NULL DEFAULT '' AFTER logo;
ALTER TABLE invoices ADD customer_email VARCHAR(190) NOT NULL DEFAULT '' AFTER customer_gstin, ADD shipping_name VARCHAR(160) NOT NULL DEFAULT '' AFTER shipping_address, ADD shipping_mobile VARCHAR(30) NOT NULL DEFAULT '' AFTER shipping_name, ADD shipping_email VARCHAR(190) NOT NULL DEFAULT '' AFTER shipping_mobile, ADD shipping_state VARCHAR(2) NOT NULL DEFAULT '' AFTER shipping_email, ADD delivery_note VARCHAR(160) NOT NULL DEFAULT '' AFTER place_of_supply, ADD payment_terms VARCHAR(160) NOT NULL DEFAULT '' AFTER delivery_note, ADD buyer_order_number VARCHAR(160) NOT NULL DEFAULT '' AFTER payment_terms, ADD buyer_order_date DATE NULL AFTER buyer_order_number, ADD dispatch_doc_number VARCHAR(160) NOT NULL DEFAULT '' AFTER buyer_order_date, ADD delivery_note_date DATE NULL AFTER dispatch_doc_number, ADD dispatch_through VARCHAR(160) NOT NULL DEFAULT '' AFTER delivery_note_date, ADD destination VARCHAR(160) NOT NULL DEFAULT '' AFTER dispatch_through, ADD terms_of_delivery VARCHAR(500) NOT NULL DEFAULT '' AFTER destination, ADD shipping_charges DECIMAL(18,2) NOT NULL DEFAULT 0 AFTER discount, ADD shipping_gst_rate DECIMAL(5,2) NOT NULL DEFAULT 0 AFTER shipping_charges, ADD shipping_gst DECIMAL(18,2) NOT NULL DEFAULT 0 AFTER shipping_gst_rate, ADD amount_paid DECIMAL(18,2) NOT NULL DEFAULT 0 AFTER grand_total, ADD amount_due DECIMAL(18,2) NOT NULL DEFAULT 0 AFTER amount_paid, ADD payment_status ENUM('Paid','Partially Paid','Due','Credit Cleared','Cancelled') NOT NULL DEFAULT 'Paid' AFTER amount_due, ADD credit_bill BOOLEAN NOT NULL DEFAULT 0 AFTER payment_status;
UPDATE invoices SET amount_paid=grand_total,amount_due=0,payment_status='Paid' WHERE status='Active' AND payment_method<>'Credit';
UPDATE invoices SET amount_paid=0,amount_due=grand_total,payment_status='Due',credit_bill=1 WHERE status='Active' AND payment_method='Credit';
UPDATE invoices SET payment_status='Cancelled' WHERE status='Cancelled';
ALTER TABLE invoice_items ADD discount_mode ENUM('Flat','Percent') NOT NULL DEFAULT 'Flat' AFTER rate, ADD discount_value DECIMAL(18,2) NOT NULL DEFAULT 0 AFTER discount_mode;
UPDATE invoice_items SET discount_value=discount;
CREATE TABLE payment_allocations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, invoice_id BIGINT UNSIGNED NOT NULL, position INT NOT NULL, method VARCHAR(40) NOT NULL, amount DECIMAL(18,2) NOT NULL, reference VARCHAR(100) NOT NULL DEFAULT '', created_by BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(invoice_id) REFERENCES invoices(id) ON DELETE CASCADE, FOREIGN KEY(created_by) REFERENCES users(id), UNIQUE(invoice_id,position), CHECK(amount>0)) ENGINE=InnoDB;
INSERT INTO payment_allocations(invoice_id,position,method,amount,reference,created_by) SELECT id,1,payment_method,grand_total,payment_reference,created_by FROM invoices WHERE status='Active' AND payment_method<>'Credit' AND grand_total>0;
CREATE TABLE credit_accounts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, customer_name VARCHAR(160) NOT NULL, customer_mobile VARCHAR(30) NOT NULL UNIQUE, customer_address TEXT NOT NULL, total_credit DECIMAL(18,2) NOT NULL DEFAULT 0, total_cleared DECIMAL(18,2) NOT NULL DEFAULT 0, balance DECIMAL(18,2) NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_credit_name(customer_name), CHECK(balance>=0)) ENGINE=InnoDB;
CREATE TABLE credit_transactions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, credit_account_id BIGINT UNSIGNED NOT NULL, invoice_id BIGINT UNSIGNED NULL, kind ENUM('Credit','Clearance','Cancellation') NOT NULL, receipt_number VARCHAR(50) NULL UNIQUE, transaction_date DATE NOT NULL, amount DECIMAL(18,2) NOT NULL, balance_after DECIMAL(18,2) NOT NULL, created_by BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(credit_account_id) REFERENCES credit_accounts(id) ON DELETE CASCADE, FOREIGN KEY(invoice_id) REFERENCES invoices(id) ON DELETE SET NULL, FOREIGN KEY(created_by) REFERENCES users(id), INDEX idx_credit_tx(credit_account_id,transaction_date,id), CHECK(amount>=0), CHECK(balance_after>=0)) ENGINE=InnoDB;
CREATE TABLE credit_transaction_allocations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, credit_transaction_id BIGINT UNSIGNED NOT NULL, position INT NOT NULL, method VARCHAR(40) NOT NULL, amount DECIMAL(18,2) NOT NULL, reference VARCHAR(100) NOT NULL DEFAULT '', FOREIGN KEY(credit_transaction_id) REFERENCES credit_transactions(id) ON DELETE CASCADE, UNIQUE(credit_transaction_id,position), CHECK(amount>0)) ENGINE=InnoDB;
INSERT INTO credit_accounts(customer_name,customer_mobile,customer_address,total_credit,total_cleared,balance) SELECT MAX(customer_name),customer_mobile,MAX(billing_address),SUM(grand_total),0,SUM(grand_total) FROM invoices WHERE status='Active' AND payment_method='Credit' AND customer_mobile<>'' GROUP BY customer_mobile;
INSERT INTO credit_transactions(credit_account_id,invoice_id,kind,transaction_date,amount,balance_after,created_by) SELECT a.id,i.id,'Credit',i.invoice_date,i.grand_total,SUM(i.grand_total) OVER (PARTITION BY i.customer_mobile ORDER BY i.invoice_date,i.id),i.created_by FROM invoices i JOIN credit_accounts a ON a.customer_mobile=i.customer_mobile WHERE i.status='Active' AND i.payment_method='Credit';
INSERT IGNORE INTO permissions VALUES ('print_invoice',0),('reset_user_password',1),('delete_users',1),('delete_transaction_data',1),('manage_credit_invoices',0),('clear_credit',0);
INSERT IGNORE INTO role_permissions SELECT 'ADMIN',id FROM permissions;
INSERT IGNORE INTO role_permissions VALUES ('OWNER','print_invoice'),('OWNER','manage_credit_invoices'),('OWNER','clear_credit'),('STAFF','print_invoice');
UPDATE system_settings SET settings=JSON_SET(settings,'$.shipping_gst_rate','0') WHERE id=1;
